<?php

declare(strict_types=1);

$root = __DIR__;
$current = $root.DIRECTORY_SEPARATOR.'resources'.DIRECTORY_SEPARATOR.'views'.DIRECTORY_SEPARATOR.'surfaces'.DIRECTORY_SEPARATOR.'pos'.DIRECTORY_SEPARATOR.'register.blade.php';

if (! is_file($current)) {
    fwrite(STDERR, "ERROR: Datei nicht gefunden: {$current}".PHP_EOL);
    exit(1);
}

if (! function_exists('proc_open')) {
    fwrite(STDERR, "ERROR: proc_open ist in PHP nicht verfuegbar.".PHP_EOL);
    exit(1);
}

$base = base64_decode('', true);
$mobile = base64_decode('', true);

if ($base === false || $mobile === false) {
    fwrite(STDERR, "ERROR: Eingebettete Merge-Daten konnten nicht gelesen werden.".PHP_EOL);
    exit(1);
}

$tmpDir = sys_get_temp_dir().DIRECTORY_SEPARATOR.'kassensystem-mobile-merge-'.bin2hex(random_bytes(5));

if (! mkdir($tmpDir, 0700, true) && ! is_dir($tmpDir)) {
    fwrite(STDERR, "ERROR: Temporaeres Verzeichnis konnte nicht erstellt werden.".PHP_EOL);
    exit(1);
}

$basePath = $tmpDir.DIRECTORY_SEPARATOR.'register.base.blade.php';
$mobilePath = $tmpDir.DIRECTORY_SEPARATOR.'register.mobile.blade.php';

file_put_contents($basePath, $base);
file_put_contents($mobilePath, $mobile);

$descriptors = [
    1 => ['pipe', 'w'],
    2 => ['pipe', 'w'],
];

$process = proc_open(
    ['git', 'merge-file', '-p', '--diff3', $current, $basePath, $mobilePath],
    $descriptors,
    $pipes,
    $root,
);

if (! is_resource($process)) {
    cleanup($tmpDir);
    fwrite(STDERR, "ERROR: git merge-file konnte nicht gestartet werden.".PHP_EOL);
    exit(1);
}

$merged = stream_get_contents($pipes[1]);
$error = stream_get_contents($pipes[2]);
fclose($pipes[1]);
fclose($pipes[2]);

$exit = proc_close($process);

if ($exit === 1) {
    $conflictFile = $root.DIRECTORY_SEPARATOR.'register.blade.php.mobile-merge-conflict';
    file_put_contents($conflictFile, $merged);
    cleanup($tmpDir);

    fwrite(STDERR, "MERGE-KONFLIKT: Die aktuelle POS-Datei enthaelt Aenderungen in denselben Bereichen.".PHP_EOL);
    fwrite(STDERR, "Die Originaldatei wurde NICHT veraendert.".PHP_EOL);
    fwrite(STDERR, "Konfliktvorschlag: {$conflictFile}".PHP_EOL);
    exit(2);
}

if ($exit !== 0) {
    cleanup($tmpDir);
    fwrite(STDERR, "ERROR: git merge-file ist fehlgeschlagen.".PHP_EOL);
    if (trim($error) !== '') {
        fwrite(STDERR, trim($error).PHP_EOL);
    }
    exit(1);
}

$backupDir = $root.DIRECTORY_SEPARATOR.'.foundation'.DIRECTORY_SEPARATOR.'compat-backups';
if (! is_dir($backupDir) && ! mkdir($backupDir, 0700, true) && ! is_dir($backupDir)) {
    cleanup($tmpDir);
    fwrite(STDERR, "ERROR: Backup-Verzeichnis konnte nicht erstellt werden.".PHP_EOL);
    exit(1);
}

$backup = $backupDir.DIRECTORY_SEPARATOR.'register.blade.php.'.date('Ymd_His').'.bak';

if (! copy($current, $backup)) {
    cleanup($tmpDir);
    fwrite(STDERR, "ERROR: Sicherheitskopie konnte nicht erstellt werden.".PHP_EOL);
    exit(1);
}

if (file_put_contents($current, $merged) === false) {
    copy($backup, $current);
    cleanup($tmpDir);
    fwrite(STDERR, "ERROR: Gemergte Datei konnte nicht geschrieben werden. Backup wurde zurueckgespielt.".PHP_EOL);
    exit(1);
}

cleanup($tmpDir);

echo "UPDATED resources/views/surfaces/pos/register.blade.php".PHP_EOL;
echo "BACKUP  ".str_replace($root.DIRECTORY_SEPARATOR, '', $backup).PHP_EOL;
echo "Mobile-POS-Aenderungen wurden mit deinem lokalen Dateistand zusammengefuehrt.".PHP_EOL;

exit(0);

function cleanup(string $directory): void
{
    if (! is_dir($directory)) {
        return;
    }

    foreach (glob($directory.DIRECTORY_SEPARATOR.'*') ?: [] as $file) {
        @unlink($file);
    }

    @rmdir($directory);
}
